const SHARE_URL=`https://fliiiiix.github.io/Kinet/`;let qrLibraryPromise=null;function loadQrLibrary(){if(window.QRCode)return Promise.resolve();if(!qrLibraryPromise){qrLibraryPromise=new Promise((resolve,reject)=>{const script=document.createElement(`script`);script.src=`https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js`;script.onload=resolve;script.onerror=reject;document.head.appendChild(script)})}return qrLibraryPromise}async function openShareModal(){document.getElementById(`shareLinkText`).textContent=SHARE_URL.replace(/^https?:\/\//,``);openOverlay(`shareOverlay`);const qrEl=document.getElementById(`shareQrCode`);if(qrEl.childElementCount)return;try{await loadQrLibrary();new QRCode(qrEl,{text:SHARE_URL,width:156,height:156,colorDark:`#0f0e16`,colorLight:`#ffffff`,correctLevel:QRCode.CorrectLevel.M})}catch(e){qrEl.innerHTML=`<div class="empty-state">QR indisponible. Le lien reste juste en dessous.</div>`;console.error(e)}}function closeShareModal(){closeOverlay(`shareOverlay`)}document.getElementById(`shareBtn`).addEventListener(`click`,openShareModal);document.getElementById(`closeShare`).addEventListener(`click`,closeShareModal);document.getElementById(`shareOverlay`).addEventListener(`click`,e=>{if(e.target.id===`shareOverlay`)closeShareModal()});document.getElementById(`copyShareLink`).addEventListener(`click`,async()=>{try{await navigator.clipboard.writeText(SHARE_URL);showToast(`Lien copié`)}catch(e){showToast(`Impossible de copier, sélectionne le lien à la main`);console.error(e)}});